//  既存の人生の章のあいだに、年代順に新しい章を差し込む。
//   ・恋人：ラブコメのような甘酸っぱい日々（英霊の性格ごとに、出来事も反応も変わる）
//   ・相棒：ドタバタで飽きない騒動の数々
//   ・主従・家族・別れの後・災厄の後・敗者・日常・士郎（凛／桜）・月の王：人生の節目を細かく
//  子の有無（data_family.js の kid()）で細部が変わる章もある
// =============================================================

function insertChapters(track, list) {
  const t = EPI[track]; if (!t) return;
  for (const ch of list) { let i = t.findIndex(s => s.y > ch.y || s.final); if (i < 0) i = t.length; t.splice(i, 0, ch); }
}
